const response = $input.first().json;
const result = JSON.parse(response.choices[0].message.content);
const { type, confidence } = result;
if (!['bug', 'task', 'feature', 'unknown'].includes(type) || typeof confidence !== 'number' || !(confidence >= 0 && confidence <= 1)) {
  throw new Error('Unexpected classifier output');
}
return [{ json: { type, confidence } }];
